function kb.xpGuess(Rbb)
local Sbb=Rbb.level and N.Levels[Rbb.level]
if not Sbb then
return 0
end
local Tbb=math.min(9,tonumber(Sbb.story_world_rank)or tonumber(Rbb.rank)or 9)
local Ubb=tonumber(Sbb.story_level_rank)or 6
local Vbb=(Rbb.kind==xre[2115]and 1.5 or 1)*(Tbb>5 and 2 or 1)
local Wbb=2.1564^(Tbb-1)*(40+10*Ubb)/Vbb
if Rbb.kind==xre[2094]then
Wbb=3*30*2.1564^(Tbb-1)/Vbb
end
local Xbb=Tbb>=9 and 0.3 or(Tbb>=7 and 0.5 or 1)
return Wbb*Xbb*6
end
