kb._xpRate,kb._xpRateAt=Zbb,os.time()
end
if Zbb<=0 then
return 0
end
local _bb=P.modes and P.modes[Ybb.key]
local acb=tonumber(_bb and _bb.xp)or kb.xpGuess(Ybb)
local bcb=acb*Zbb
if bcb<1 then
return 0
end
return bcb,string.format(xre[3110],U.fmt(acb),math.floor(bcb+0.5))
end
