while U.now()-Hcb<4 and(tonumber((xcb.collection:get_unit_by_uuid(wcb.uuid)or ycb).xp)or 0)<=Dcb do
task.wait(0.25)
end
local Icb=xcb.collection:get_unit_by_uuid(wcb.uuid)or ycb
local Jcb=(tonumber(Icb.xp)or 0)-Dcb
if Jcb>0 then
local Kcb=kb.level(Icb)
local Lcb=Kcb>Ecb and string.format(xre[3108],Ecb,Kcb)or string.format(xre[3109],Ecb)
cb.add(string.format(xre[3115],Ccb,wcb.name),Ccb,xre[3116],string.format(xre[3117],U.fmt(Jcb),Lcb))
kb.note(string.format(xre[3118],wcb.name,Ccb,U.fmt(Jcb),Lcb,math.abs(Jcb-Bcb)>Bcb*0.1 and string.format(xre[3119],U.fmt(Bcb))or xre[993]))
else
