end
for ieb,jeb in ipairs(Sdb.eats or{})do
table.insert(feb,string.format(xre[3167],jeb.amount,V.name(jeb.id)))
end
local keb=string.format(xre[3168],V.name(Sdb.from),V.name(Sdb.to),U.fmt(Sdb.scoreFrom or 0),U.fmt(Sdb.scoreTo or 0))
cb.add(xre[3169]..keb,1,xre[3170],(Tdb or xre[3171])..(#feb>0 and(xre[3172]..table.concat(feb,xre[2187]))or xre[993]))
F.log(1,xre[3173],keb..xre[3174]..(Tdb or xre[3171])..(#feb>0 and(xre[3172]..table.concat(feb,xre[2187]))or xre[993]))
W._sigAt=nil
pcall(hb.refresh)
return true,V.name(Sdb.to)..xre[3175]
end
F.log(1,xre[3173],xre[3176]..V.name(Sdb.from)..xre[2764]..tostring(aeb)..xre[3177]..tostring(beb and beb.unit_id))
return false,xre[3178]..tostring(aeb)..xre[2736]
