function eb.upgradeGain(KBb,LBb,MBb,NBb,OBb,PBb)
local QBb,RBb=LBb[MBb],LBb[MBb+1]
local SBb=(QBb.cd>0 and QBb.damage/QBb.cd or 0)
local TBb=(RBb.cd>0 and RBb.damage/RBb.cd or 0)*V.aoe(RBb.atk,RBb.range)/math.max(0.3,V.aoe(QBb.atk,QBb.range))
local UBb=SBb>0 and KBb*(TBb/SBb-1)or(PBb or 0)
local VBb=LBb[MBb+2]
if VBb and MBb+1<LBb.max and VBb.cd>0 and RBb.cd>0 and SBb>0 then
local WBb=KBb*((VBb.damage/VBb.cd)/SBb-1)
local XBb=NBb+VBb.cost*OBb
if WBb/XBb>UBb/NBb then
UBb=UBb+(WBb/XBb*NBb-UBb)*0.5
end
end
local YBb=(RBb.range or 0)>(QBb.range or 0)and(1+((RBb.range-QBb.range)/math.max(1,QBb.range)))or 1
return math.max(0,UBb)*YBb
end
function eb.dpsFor(ZBb,_Bb)
if _Bb<=0 then
return 0
end
local aCb={}
for bCb,cCb in ipairs(ZBb)do
if not cCb.farm and not cCb.grif and cCb.gain>0 then
table.insert(aCb,cCb)
end
end
table.sort(aCb,function(dCb,eCb)
return dCb.gain/dCb.cost>eCb.gain/eCb.cost
end)
local fCb,gCb=0,0
for hCb,iCb in ipairs(aCb)do
if _Bb<=0 then
break
end
gCb=iCb.gain/iCb.cost
local jCb=math.min(1,_Bb/iCb.cost)
fCb=fCb+iCb.gain*jCb
_Bb=_Bb-iCb.cost*jCb
end
return fCb+math.max(0,_Bb)*gCb*0.7
end
function eb.shieldDps(kCb,lCb,mCb,nCb,oCb,pCb,qCb)
if(nCb or 0)<=0 or(kCb or 0)<=0 or(oCb or 0)<=0 then
return kCb or 0
end
lCb,mCb,pCb=math.max(0.3,lCb or 2),math.max(1,mCb or 1),pCb or 1
local rCb=kCb*pCb*lCb/mCb
return oCb*mCb/((nCb/math.max(1,qCb or 1)+math.max(1,oCb/rCb))*lCb)/pCb
end
function eb.shieldGain(sCb,tCb,uCb,vCb,wCb,xCb,yCb,zCb)
local ACb,BCb=V.attackInfo(tCb.atk,tCb.range),V.attackInfo(vCb.atk,vCb.range)
local CCb=eb.shieldDps(sCb,(tonumber(tCb.cd)or 2)*(yCb or 1),ACb.n,wCb,xCb,zCb,ACb.hits)
local DCb=eb.shieldDps(uCb,(tonumber(vCb.cd)or 2)*(yCb or 1),BCb.n,wCb,xCb,zCb,BCb.hits)
local ECb=math.max(0,((tonumber(vCb.range)or 0)-(tonumber(tCb.range)or 0))/math.max(1,tonumber(tCb.range)or 1))
return math.max(0,DCb-CCb)+CCb*ECb
end
function eb.shieldWork(FCb,GCb,HCb,ICb,JCb,KCb,LCb,MCb,NCb)
if(ICb or 0)<=0 then
return 0
end
local OCb=3*ICb*(JCb or 1)/math.max(1,KCb or 20)
if(HCb or 0)>=OCb then
return 0
end
return math.max(1,FCb or 1)*math.max(1,NCb or 1)/math.max(0.3,GCb or 2)*math.min(LCb or 0,MCb or 0)
end
function eb.holdGain(PCb,QCb,RCb,SCb)
if not PCb or(QCb or 0)<=0 then
return 0
end
local TCb,UCb=tonumber(PCb.stun)or 0,tonumber(PCb.slowTime)or 0
if TCb<=0 and UCb<=0 then
return 0
end
local VCb,WCb=TCb>0 and TCb or UCb,TCb>0 and 1 or(tonumber(PCb.slowPct)or 0.3)
local XCb=WCb*VCb/(VCb+(tonumber(PCb.ccCd)or 8))
local YCb=XCb/math.max(0.1,1-XCb)
return QCb*YCb*U.clamp(RCb or 0.5,0,1)*math.min(1,(tonumber(PCb.n)or 1)/2)/(1+(SCb or 0))
end
function eb.bleedGain(ZCb,_Cb,aDb,bDb)
if(ZCb or 0)<=0 then
return 0
end
local cDb=_Cb or 0
for dDb,eDb in ipairs(aDb or{})do
cDb=math.max(cDb,(tonumber(eDb.hp)or 0)*0.5)
end
return ZCb*cDb*(bDb and 0.5 or 1)
end
function eb.bleedShare(fDb,gDb,hDb,iDb)
if fDb<=0 or not gDb then
return 0
end
if iDb then
return gDb==0 and fDb or fDb/(gDb+1)
end
return hDb<gDb and fDb/(gDb-hDb)or 0
end
function eb.keepsUp(jDb,kDb,lDb,mDb,nDb)
local oDb=jDb.coming
if not(oDb and#oDb>0 and jDb.waveSec)then
return true
end
local pDb=jDb.eff or 1
local qDb=jDb.money-lDb
local rDb=(jDb.teamDps or 0)*(jDb.shieldK or 1)+(mDb or 0)*pDb+eb.dpsFor(kDb,math.max(0,qDb))*pDb
local sDb=(jDb.farmNow or 0)+(nDb or 0)
local tDb=(jDb.roadSec or 130)*U.clamp(jDb.cover or 0.6,0.1,1)
local uDb=jDb.hpAlive or 0
for vDb,wDb in ipairs(oDb)do
uDb=math.max(0,uDb+wDb.hp-rDb*jDb.waveSec)
local xDb=rDb*tDb
if uDb>xDb then
return false,vDb,xDb/math.max(1,uDb)
end
if vDb< #oDb then
rDb=rDb+eb.dpsFor(kDb,(wDb.reward or 0)+sDb)*pDb*(0.85^vDb)
end
end
return true
end
function eb.decide(yDb,zDb)
local ADb=U.clamp(zDb.cover or 0.6,0.1,1)
local BDb=math.max(O.clearSec,0.7*(zDb.roadSec or 50)*ADb)
local CDb=(zDb.clearSec or 0)>BDb
zDb.piling=zDb.piling and CDb
local DDb=zDb.attackers>0 and zDb.pressure<math.min(O.safeReach,ADb*0.75)and not zDb.piling and not CDb
local EDb=zDb.pressure>=math.min(O.dangerReach,ADb*0.9)or(zDb.piling and zDb.enemies>=18)
local FDb,GDb
for HDb,IDb in ipairs(yDb)do
if IDb.farm then
if O.farmUnits and IDb.gain>0 then
IDb.payback=IDb.cost/IDb.gain
if zDb.left-1>=IDb.payback+(zDb.farmSpare or O.farmSpare)and(not FDb or IDb.payback<FDb.payback)then
FDb=IDb
end
end
else
IDb.ratio=IDb.gain/math.max(1,IDb.cost)
if not GDb or IDb.ratio>GDb.ratio then
GDb=IDb
end
end
end
if zDb.leak and zDb.attackers>0 then
local JDb
for KDb,LDb in ipairs(yDb)do
local MDb=not zDb.airLeak or(LDb.e and bb.cardAir(LDb.e.id))
if LDb.place and not LDb.farm and not LDb.idol and not LDb.grif and MDb and LDb.cost<=zDb.money and not(LDb.e and V.allyBuff(LDb.e.id))and(not JDb or LDb.gain>JDb.gain)then
JDb=LDb
end
end
if JDb then
return JDb,string.format(xre[3709],math.floor(zDb.leak*100))
end
end
local NDb=zDb.future<zDb.wantLeft*1.1
local ODb,PDb,QDb=true,nil,nil
if FDb then
ODb,PDb,QDb=eb.keepsUp(zDb,yDb,FDb.cost,0,FDb.gain)
end
local RDb=zDb.coming and not eb.keepsUp(zDb,yDb,0,0,0)
local SDb=false
if bb.random and FDb and not EDb and zDb.attackers>=2 and FDb.payback<=zDb.left/3 then
local TDb=0
for UDb,VDb in ipairs(bb.mine or{})do
if V.isFarm(VDb._stats.id.Value)then
TDb=TDb+1
end
end
SDb=not FDb.place or TDb<4
end
if RDb and zDb.attackers>0 then
EDb=true
end
if EDb and GDb and GDb.grif then
GDb=nil
for WDb,XDb in ipairs(yDb)do
if not XDb.farm and not XDb.grif and(not GDb or XDb.ratio>GDb.ratio)then
GDb=XDb
end
end
end
local YDb=math.max(1,zDb.incomeRate or 20)
local ZDb=zDb.waveSec or 20
local function _Db(aEb,bEb,cEb)
local dEb=math.max(0,(aEb.cost-zDb.money)/YDb)
local eEb=aEb.gain*math.max(0,cEb-dEb)
if bEb then
local fEb=math.max(0,zDb.money-aEb.cost)
local gEb=dEb+math.max(0,(bEb.cost-fEb)/YDb)
eEb=eEb+bEb.gain*math.max(0,cEb-gEb)
end
return eEb
end
local hEb,iEb
if zDb.attackers==0 and GDb then
local jEb=4*ZDb
local kEb={}
for lEb,mEb in ipairs(yDb)do
if mEb.place and not mEb.farm and not mEb.grif then
table.insert(kEb,{o=mEb,v=_Db(mEb,nil,jEb)})
end
end
table.sort(kEb,function(nEb,oEb)
return nEb.v>oEb.v
end)
local pEb=zDb.opener and kEb[zDb.opener]and zDb.opener or 1
local qEb=kEb[pEb]and kEb[pEb].o
hEb,iEb=qEb or GDb,pEb>1 and xre[3710]or xre[3711]
elseif FDb and DDb and NDb and not EDb and ODb then
hEb=FDb
iEb=string.format(xre[3712],FDb.payback,zDb.left,zDb.coming and#zDb.coming or 0)
elseif SDb then
hEb=FDb
iEb=string.format(xre[3713],FDb.payback,zDb.left)
elseif GDb then
hEb=GDb
if RDb then
iEb=string.format(xre[3714])
elseif EDb then
iEb=string.format(xre[3715],math.floor(zDb.pressure*100),math.floor(ADb*100))
elseif FDb and not ODb then
iEb=string.format(xre[3716],PDb or 1,math.floor((QDb or 0)*100))
elseif FDb and CDb then
iEb=string.format(xre[3717],math.min(999,math.floor(zDb.clearSec)),math.floor(BDb))
elseif FDb and zDb.piling then
iEb=string.format(xre[3718],zDb.enemies)
elseif FDb and not DDb then
iEb=xre[3719]
elseif FDb and not NDb then
iEb=xre[3720]
else
iEb=xre[3721]
end
end
if not hEb then
return nil
end
if hEb.cost>zDb.money then
local rEb
if not hEb.farm then
local sEb=((zDb.pressure or 0)>=0.95 and 0.5 or EDb and 2 or 6)*ZDb
local tEb
for uEb,vEb in ipairs(yDb)do
if not vEb.farm and vEb~=hEb and vEb.cost<=zDb.money and not(EDb and vEb.grif)then
local wEb=_Db(vEb,hEb,sEb)
local xEb=_Db(hEb,vEb,sEb)
if wEb>xEb and(not tEb or wEb>tEb)then
rEb,tEb=vEb,wEb
end
end
end
end
if not rEb then
return nil,nil,string.format(xre[3722],U.fmt(hEb.cost),hEb.what or xre[2310],math.ceil((hEb.cost-zDb.money)/YDb),math.floor(YDb),iEb),{cost=hEb.cost,what=hEb.what,sec=math.ceil((hEb.cost-zDb.money)/YDb),rate=math.floor(YDb),why=iEb}
end
hEb,iEb=rEb,iEb..xre[3723]
end
return hEb,iEb
end
