function gb.cal(DEb)
local EEb=P.simCal[DEb]
if not EEb then
EEb={}
P.simCal[DEb]=EEb
end
return EEb
end
function gb.effFor(FEb)
local GEb,HEb=0,0
for IEb,JEb in pairs(P.simCal)do
local KEb,LEb=tonumber(JEb.eff),tonumber(JEb.n)or 0
if KEb and LEb>0 then
GEb=GEb+KEb*LEb
HEb=HEb+LEb
end
end
local MEb=HEb>0 and GEb/HEb or gb.PRIOR.eff
local NEb,OEb=tonumber(FEb and FEb.eff),tonumber(FEb and FEb.n)or 0
if not NEb then
return MEb
end
