function jb.roomLearn(Zoc)
if Zoc or bb.kind~=xre[2095]or bb.roomLearned then
return
end
local _oc=P.dg.room
local apc,bpc=bb.pred,bb.calRun
if type(_oc)~=xre[2074]or _oc.seed==nil or type(apc)~=xre[2074]or not apc.won or type(bpc)~=xre[2074]then
return
end
local function cpc(dpc,epc)
return type(dpc)==xre[2074]and tonumber(dpc[epc]or dpc[tostring(epc)])or nil
end
local fpc={}
for gpc=2,bb.wave()do
local hpc,ipc=cpc(bpc.alive,gpc),cpc(apc.aliveAt,gpc)
if hpc and ipc and hpc>0 and ipc>0 then
table.insert(fpc,hpc/ipc)
end
end
if#fpc<3 then
