end
table.sort(fpc)
local jpc=fpc[math.ceil(#fpc/2)]
bb.roomLearned=true
if jpc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==xre[2074]and P.dg.roomK or{}
local kpc=tostring(_oc.seed)
local lpc=P.dg.roomK[kpc]
local mpc=math.min(jb.ROOM_K_MAX,jb.roomK(kpc)*jpc)
P.dg.roomK[kpc]={k=mpc,n=(type(lpc)==xre[2074]and tonumber(lpc.n)or 0)+1,at=os.time(),d=_oc.d}
bb.roomKUp=true
