end
table.sort(npc,function(qpc,rpc)
return qpc.at>rpc.at
end)
for spc=31,#npc do
P.dg.roomK[npc[spc].s]=nil
end
F.log(1,xre[3998],string.format(xre[4117],tostring(_oc.d),jpc,mpc))
end
