function bb.buildPath()
bb.samples={}
local Vpc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not Vpc then
return
end
for Wpc,Xpc in pairs(Vpc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[Wpc.Name])then
local Ypc={}
for Zpc,_pc in ipairs(Xpc.points or{})do
table.insert(Ypc,_pc.part.Position)
end
local aqc=0
for bqc=2,#Ypc do
aqc=aqc+(Ypc[bqc]-Ypc[bqc-1]).Magnitude
end
local cqc=0
for dqc=2,#Ypc do
local eqc,fqc=Ypc[dqc-1],Ypc[dqc]
local gqc=(fqc-eqc).Magnitude
local hqc=math.max(1,math.floor(gqc/2))
for iqc=0,hqc-1 do
local jqc=eqc:Lerp(fqc,iqc/hqc)
table.insert(bb.samples,{pos=jqc,prog=(cqc+gqc*iqc/hqc)/math.max(1,aqc),lane=Wpc.Name})
end
cqc=cqc+gqc
end
if Ypc[#Ypc]then
table.insert(bb.samples,{pos=Ypc[#Ypc],prog=1,lane=Wpc.Name})
end
end
end
pcall(bb.readHidden,Vpc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local kqc=tonumber(bb.ld and bb.ld._portal_lanes)
local lqc=gb.laneList(bb.samples)
if kqc and kqc>=1 and lqc and#lqc>kqc then
bb.laneWant=kqc
end
bb.laneTotal=lqc and#lqc or 1
bb.countLanes()
end
function bb.readHidden(mqc)
local nqc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(nqc)~=xre[2074]or not next(nqc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local oqc
for pqc,qqc in pairs(mqc)do
if nqc[pqc.Name]and type(qqc.points)==xre[2074]and#qqc.points>=2 then
local rqc={}
for sqc,tqc in ipairs(qqc.points)do
rqc[sqc]=U.flat(tqc.part.Position)
end
local uqc={}
for vqc,wqc in ipairs(bb.samples)do
local xqc=tostring(wqc.lane)
uqc[xqc]=uqc[xqc]or{}
table.insert(uqc[xqc],wqc)
end
local yqc,zqc
for Aqc,Bqc in pairs(uqc)do
local Cqc=0
for Dqc=1,#rqc,math.max(1,math.floor(#rqc/20))do
local Eqc=math.huge
for Fqc,Gqc in ipairs(Bqc)do
local Hqc=(U.flat(Gqc.pos)-rqc[Dqc]).Magnitude
if Hqc<Eqc then
Eqc=Hqc
end
end
Cqc=Cqc+Eqc
end
if not zqc or Cqc<zqc then
yqc,zqc=Aqc,Cqc
end
end
local Iqc,Jqc,Kqc,Lqc,Mqc,Nqc={},nil,nil,nil,0,0
for Oqc,Pqc in ipairs(rqc)do
local Qqc,Rqc=nil,math.huge
for Sqc,Tqc in ipairs(uqc[yqc])do
local Uqc=(U.flat(Tqc.pos)-Pqc).Magnitude
if Uqc<Rqc then
Rqc,Qqc=Uqc,Tqc.prog
end
end
Nqc=math.max(Nqc,Rqc)
if Kqc then
local Vqc=Qqc-Kqc
local Wqc=(Vqc>0.002 and 1)or(Vqc< -0.002 and-1)or Lqc
if Lqc and Wqc and Wqc~=Lqc then
table.insert(Iqc,math.floor(Kqc*1000+0.5)/1000)
end
Lqc,Mqc=Wqc or Lqc,Mqc+math.abs(Vqc)
else
Jqc=Qqc
end
Kqc=Qqc
if Oqc%50==0 then
task.wait()
end
end
if Kqc and Nqc<=8 then
table.insert(Iqc,math.floor(Kqc*1000+0.5)/1000)
oqc=oqc or{}
oqc[pqc.Name]={from=math.floor((Jqc or 0)*1000+0.5)/1000,len=math.floor(Mqc*1000+0.5)/1000,turns=Iqc,road=yqc}
end
end
end
if not oqc then
return
end
local Xqc=bb.ld.map
P.maps[Xqc]=P.maps[Xqc]or{}
local Yqc=P.maps[Xqc].hidden
P.maps[Xqc].hidden=oqc
if type(Yqc)~=xre[2074]then
for Zqc,_qc in pairs(oqc)do
F.log(1,xre[2743],string.format(xre[4133],Zqc,_qc.len,tostring(_qc.road),math.floor((#_qc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local arc,brc,crc={},0,0
for drc,erc in ipairs(bb.samples)do
local frc=tostring(erc.lane)
if not arc[frc]then
brc=brc+1
end
arc[frc]=(arc[frc]or 0)+1
crc=crc+1
end
bb.laneCount={n=brc,by=arc,avg=brc>0 and crc/brc or 1}
if brc>=2 then
local grc,hrc=pcall(gb.laneSep,bb.samples)
local irc=P.maps[bb.mapKey()]
if grc and hrc and type(irc)==xre[2074]then
irc.sep=hrc
end
end
end
