function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local jrc,krc={},0
for lrc,mrc in ipairs(workspace._UNITS:GetChildren())do
local nrc=mrc:FindFirstChild(xre[2138])
if nrc and nrc:FindFirstChild(xre[4134])and nrc.player.Value==nil and nrc:FindFirstChild(xre[4135])and mrc:FindFirstChild(xre[3331])then
local orc=tostring(nrc.lane.Value)
if not jrc[orc]then
jrc[orc]=true
krc=krc+1
end
end
end
if krc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,xre[2743],xre[4136])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if krc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local prc,qrc={},{}
for rrc,trc in ipairs(bb.samples)do
if jrc[tostring(trc.lane)]then
table.insert(prc,trc)
end
end
if#prc==0 then
bb.laneWant=nil
return true
end
for urc in pairs(jrc)do
table.insert(qrc,urc)
end
table.sort(qrc)
bb.samples,bb.laneCut=prc,table.concat(qrc,xre[2389])
bb.countLanes()
local vrc,wrc=pcall(bb.buildCandidates)
if not vrc then
F.log(1,xre[2461],xre[4137]..tostring(wrc))
end
F.log(1,xre[2743],string.format(xre[4138],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local xrc,yrc=pcall(bb.planSpots)
bb.planning=nil
if not xrc then
F.log(1,xre[2461],xre[4139]..tostring(yrc))
end
end)
end
return true
end
function bb.buildWaves()
