if U.count(P.layoutRec)>80 then
local POc,QOc
for ROc,SOc in pairs(P.layoutRec)do
local TOc=type(SOc)==xre[2074]and tonumber(SOc.at)or 0
if not QOc or TOc<QOc then
POc,QOc=ROc,TOc
end
end
P.layoutRec[POc]=nil
