end
function bb.layoutAdd(UOc,VOc,WOc,XOc,YOc)
UOc.runs,UOc.wins=(tonumber(UOc.runs)or 0)+1,(tonumber(UOc.wins)or 0)+(VOc and 1 or 0)
UOc.sec,UOc.wave=type(UOc.sec)==xre[2074]and UOc.sec or{},type(UOc.wave)==xre[2074]and UOc.wave or{}
if VOc and tonumber(WOc)then
table.insert(UOc.sec,math.floor(WOc+0.5))
end
table.insert(UOc.wave,tonumber(XOc)or 0)
if tonumber(YOc)then
UOc.kills=type(UOc.kills)==xre[2074]and UOc.kills or{}
table.insert(UOc.kills,math.floor(tonumber(YOc)))
while#UOc.kills>bb.LAYOUT_KEEP do
table.remove(UOc.kills,1)
end
end
while#UOc.sec>bb.LAYOUT_KEEP do
table.remove(UOc.sec,1)
end
while#UOc.wave>bb.LAYOUT_KEEP do
table.remove(UOc.wave,1)
end
end
function bb.layoutJudge(ZOc,_Oc,aPc,bPc,cPc)
cPc=cPc or xre[4328]
local dPc,ePc=tonumber(ZOc and ZOc.runs)or 0,tonumber(_Oc and _Oc.runs)or 0
if dPc<1 or ePc<bb.LAYOUT_CONTROL then
return nil
end
if bPc and type(ZOc.kills)==xre[2074]and type(_Oc.kills)==xre[2074]and#ZOc.kills>=1 and#_Oc.kills>=bb.LAYOUT_CONTROL then
local fPc,gPc=bb.labMedian(ZOc.kills),bb.labMedian(_Oc.kills)
if fPc and gPc and fPc<gPc*0.97 and(#ZOc.kills>=2 or fPc<gPc*0.85)then
return string.format(xre[4329],fPc,gPc,cPc)
end
