local WRc=(bb.kind==xre[2095]or bb.style==xre[3767]or bb.style==xre[3768])and not WQc and not(JRc and JRc.leak)and not V.isFarm(VQc.id)and V.range(VQc.u,V.rows(VQc.id).max)*URc or nil
local XRc=V.allyBuff(VQc.id)
if bb.killZone()and not WQc and not XQc and not XRc and not(JRc and JRc.leak)and not V.isFarm(VQc.id)then
local YRc=WRc or VRc
local ZRc={}
