local hbd={}
for ibd,jbd in pairs(bb.ownDealt or{})do
if not V.isFarm(jbd.id)then
hbd[jbd.id]=(hbd[jbd.id]or 0)+(tonumber(jbd.v)or 0)
end
end
for kbd,lbd in pairs(bb.helperDealt or{})do
if lbd.owner and V.SUMMONER[lbd.owner]and not V.droneHelper(lbd)then
hbd[lbd.owner]=(hbd[lbd.owner]or 0)+(tonumber(lbd.v)or 0)
end
end
local mbd=type(bb.calRun.potExp)==xre[2074]and bb.calRun.potExp or{}
local nbd,obd=0,0
local pbd={}
for qbd,rbd in pairs(gbd)do
if rbd>0 then
nbd,obd=nbd+(hbd[qbd]or 0),obd+rbd
local sbd=tonumber(mbd[qbd])or rbd
if sbd>0 then
table.insert(pbd,{id=qbd,r=(hbd[qbd]or 0)/sbd,w=sbd})
end
end
end
if nbd<=0 or obd<=0 then
return
end
table.sort(pbd,function(tbd,ubd)
return tbd.r<ubd.r
end)
local function vbd(wbd)
local xbd,ybd=0,0
for zbd,Abd in ipairs(pbd)do
if Abd.id~=wbd then
xbd=xbd+Abd.w
end
end
if xbd<=0 then
return nil
end
for Bbd,Cbd in ipairs(pbd)do
if Cbd.id~=wbd then
ybd=ybd+Cbd.w
if ybd>=xbd/2 then
return Cbd.r
end
end
end
end
