local Ibd=U.clamp(((hbd[Dbd]or 0)/Ebd)/Fbd,0.2,6)
bb.lastEff[Dbd]=math.floor(Ibd*1000+0.5)/1000
Gbd.eff=Gbd.eff+(Ibd-Gbd.eff)*Hbd
Gbd.n=Gbd.n+1
P.learn[Dbd]=Gbd
end
end
local Jbd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Jbd and next(bb.lastEff)then
