local Kbd=type(P.mapLearn[Jbd])==xre[2074]and P.mapLearn[Jbd]or{}
for Lbd,Mbd in pairs(bb.lastEff)do
local Nbd=type(Kbd[Lbd])==xre[2074]and Kbd[Lbd]or{eff=Mbd,n=0,v=6}
if(tonumber(Nbd.v)or 0)<4 then
Nbd.eff,Nbd.v=(tonumber(Nbd.eff)or Mbd)*V.secRescale(Lbd),4
end
if(tonumber(Nbd.v)or 0)<5 then
Nbd.eff,Nbd.v=(tonumber(Nbd.eff)or Mbd)*(V.sumRescale(Lbd)or 1),5
end
if(tonumber(Nbd.v)or 0)<6 then
Nbd.eff,Nbd.v=(tonumber(Nbd.eff)or Mbd)*(1-(V.SUMMONER[Lbd]and V.SUMMONER[Lbd].droneShare or 0)),6
end
local Obd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Nbd.n)or 0))))
Nbd.eff=(tonumber(Nbd.n)or 0)==0 and Mbd or((tonumber(Nbd.eff)or Mbd)+(Mbd-(tonumber(Nbd.eff)or Mbd))*Obd)
Nbd.n=(tonumber(Nbd.n)or 0)+1
Kbd[Lbd]=Nbd
end
Kbd._at=os.time()
P.mapLearn[Jbd]=Kbd
if U.count(P.mapLearn)>80 then
local Pbd,Qbd
for Rbd,Sbd in pairs(P.mapLearn)do
if not Qbd or(tonumber(Sbd._at)or 0)<Qbd then
