bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(Ahd,Bhd)
local Chd=(Bhd.t or 0)-(Ahd.t or 0)
if Chd<bb.BASE_WIN-1 then
return false
end
local Dhd=((tonumber(Ahd.base)or 0)-(tonumber(Bhd.base)or 0))/Chd
if Dhd<=0 or(tonumber(Bhd.base)or 0)<=0 then
return false
end
local Ehd=Bhd.base/Dhd
local Fhd,Ghd=0,0
local Hhd,Ihd=Ahd.foes or{},Bhd.foes or{}
for Jhd,Khd in pairs(Ihd)do
if Khd.prog>=bb.BASE_END then
Fhd=Fhd+Khd.hp
local Lhd=Hhd[Jhd]
if Lhd then
Ghd=Ghd+math.max(0,Lhd.hp-Khd.hp)
end
end
end
for Mhd,Nhd in pairs(Hhd)do
if Nhd.prog>=bb.BASE_END and not Ihd[Mhd]then
Ghd=Ghd+Nhd.hp
end
end
if Fhd<=0 then
return false
end
local Ohd=Ghd/Chd
local Phd=Ohd>0 and Fhd/Ohd or math.huge
local Qhd={baseTime=Ehd,loss=Dhd,atEnd=Fhd,rate=Ohd,killTime=Phd}
return Ehd<bb.BASE_SOON and Phd>Ehd*bb.BASE_MARGIN,Qhd
end
