function bb.leakAhead(sid)
local tid=0
local vid=U.flat(sid.pos)
for wid,xid in ipairs(bb.mine or{})do
local yid=xid:FindFirstChild(xre[2138])
local zid=yid and yid:FindFirstChild(xre[2452])
local Aid=yid and yid:FindFirstChild(xre[2327])
if zid and Aid and not V.isFarm(zid.Value)and not V.allyBuff(zid.Value)then
local Bid,Cid=U.flat(xid:GetPivot().Position),Aid.Value
if(not sid.fly or bb.canAir(xid))and(Bid-vid).Magnitude>Cid then
for Did,Eid in ipairs(bb.samples or{})do
if Eid.prog>sid.prog and(U.flat(Eid.pos)-Bid).Magnitude<=Cid then
tid=tid+1
break
end
end
end
end
end
return tid
end
function bb.leakStep(Fid)
if not Fid then
if bb.kind~=xre[2095]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local Gid=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==xre[2074]and P.dg.bails or{}
if not Fid and(tonumber(P.dg.bails[Gid])or 0)>=bb.BAIL_MAX then
return
end
local Hid=workspace:FindFirstChild(xre[4647])and workspace._BASES:FindFirstChild(xre[4134])
local Iid=Hid and Hid:FindFirstChild(xre[4366])and Hid.base:FindFirstChild(xre[4367])
local Jid=Iid and Iid:FindFirstChildOfClass(xre[2470])
if not Jid or Jid.Health<=0 then
return
end
local Kid=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local Lid=U.now()
bb.leakTrack=bb.leakTrack or{}
local Mid=bb.leakTrack
local Nid,Oid={},nil
for Pid,Qid in ipairs(bb.enemies or{})do
if Qid.m then
Nid[Qid.m]=true
local Rid,Sid=tonumber(Qid.hp)or 0,tonumber(Qid.prog)or 0
local Tid=Mid[Qid.m]
if not Tid then
Mid[Qid.m]={t=Lid,hp=Rid,prog=Sid}
else
if Lid-Tid.t>=bb.LEAK_WIN then
Tid.pace,Tid.net=(Sid-Tid.prog)/(Lid-Tid.t),(Tid.hp-Rid)/(Lid-Tid.t)
Tid.t,Tid.hp,Tid.prog=Lid,Rid,Sid
end
if Tid.pace and Tid.pace>0 and Rid>0 then
local Uid=(1-Sid)/Tid.pace
local Vid=math.max(0,Tid.net or 0)
local Wid=Rid-Vid*Uid
if Wid>0 and Uid<=bb.LEAK_SOON and Uid>=bb.LEAK_MIN then
local Xid=Qid.m:FindFirstChildOfClass(xre[2470])
local Yid=Jid.Health/math.max(1,Kid*(Xid and Xid.MaxHealth or Rid))
local Zid=Vid>0 and Wid/Vid or math.huge
if Zid>Yid*bb.LEAK_MARGIN and(Uid<=bb.LEAK_AHEAD or bb.leakAhead(Qid)==0)and(not Oid or Uid<Oid.left)then
Oid={left=Uid,arriving=Wid,net=Vid,baseTime=Yid,hp=Rid}
end
end
end
end
end
end
for ajd in pairs(Mid)do
