end
bb.bailNote(Gid,xre[4641])
F.log(1,xre[2743],string.format(xre[4649],bb.wave(),tonumber(bb.total)or 0,math.floor(Oid.left+0.5),U.fmt(Oid.hp),U.fmt(Oid.arriving),U.fmt(Oid.net),Oid.baseTime))
pcall(F.saveNow)
F.request(xre[2146],xre[4182])
end
