function bb.allPast(bjd)
local cjd={}
for djd,ejd in ipairs(bb.mine or{})do
local fjd=ejd._stats
local gjd=fjd.id.Value
if not V.isFarm(gjd)and not V.allyBuff(gjd)and fjd:FindFirstChild(xre[2327])then
local hjd=tonumber(fjd.range.Value)or 0
local ijd=bb.coverMax[ejd]
if not(ijd and ijd.r==hjd)then
local jjd,kjd=U.flat(ejd:GetPivot().Position),-1
for ljd,mjd in ipairs(bb.samples or{})do
if mjd.prog>kjd and(U.flat(mjd.pos)-jjd).Magnitude<=hjd then
kjd=mjd.prog
end
end
ijd={r=hjd,far=kjd}
bb.coverMax[ejd]=ijd
end
table.insert(cjd,{far=ijd.far,air=bb.canAir(ejd)})
end
end
if#cjd==0 then
return false
end
for njd,ojd in ipairs(bjd)do
for pjd,qjd in ipairs(cjd)do
if(not ojd.fly or qjd.air)and qjd.far>=(tonumber(ojd.prog)or 0)then
return false
end
end
end
return true
end
